<template>
  <!-- 对话框 - 底部展示 -->
  <div v-if="showDialog" class="dialog-container">
    <div class="dialog-box">
      <!-- 头部：NPC名称和关闭按钮 -->
      <div class="dialog-header">
        <div class="npc-info">
          <span class="npc-avatar">{{ npcName?.charAt(0) || 'N' }}</span>
          <span class="npc-name">{{ npcName || '对话' }}</span>
        </div>
        <button class="close-btn" @click="hide">×</button>
      </div>

      <!-- NPC话术区域 - 点击可跳过打字动画 -->
      <div class="dialog-content" @click="skipTypingAnimation">
        <p class="dialog-text">{{ displayedText }}<span v-if="isTyping" class="typing-cursor">|</span></p>
      </div>

      <!-- 对话选项区域 - 使用grid实现高度过渡 -->
      <div class="dialog-options-wrapper" :class="{ 'has-options': dialogOptions.length > 0 }">
        <div class="dialog-options" :class="{ 'has-audio': hasAudioOptions, 'no-audio': !hasAudioOptions }">
          <div
            v-for="(option, index) in dialogOptions"
            :key="option.id"
            class="option-item option-animate"
            :style="{ animationDelay: `${index * 0.1}s` }"
          >
            <!-- 选项按钮 -->
            <button
              class="option-btn"
              @click="handleOptionClick(option)"
            >
              {{ option.text }}
            </button>
            <!-- 如果选项有音频，显示独立的播放按钮 -->
            <button
              v-if="option.audio"
              class="audio-play-btn"
              :class="{ 'is-playing': playingOptionId === option.id }"
              @click.stop="handlePlayAudio(option)"
              :disabled="playingOptionId !== null && playingOptionId !== option.id"
              :title="playingOptionId === option.id ? '正在播放...' : '播放语音'"
            >
              <!-- 默认喇叭图标 -->
              <span v-if="playingOptionId !== option.id" class="audio-icon-static">🔊</span>
              <!-- 播放中声波动画 -->
              <span v-else class="sound-wave">
                <span class="wave-bar"></span>
                <span class="wave-bar"></span>
                <span class="wave-bar"></span>
              </span>
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts" setup>
import { ref, computed } from 'vue';
import type { NPCInteractionData, DialogueOption } from '@tencent/viewer-sdk';
const showDialog = ref(false);
let fullText = '';
const displayedText = ref('');

// NPC对话系统状态
const npcName = ref('');
const dialogOptions = ref<DialogueOption[]>([]);
const currentDialogues = ref<DialogueOption[]>([]);
const showLegacyButton = ref(false);
let currentInteractionData: NPCInteractionData | null = null;

const isTyping = ref(false);

// 计算选项是否包含音频 - 用于决定布局样式
const hasAudioOptions = computed(() => {
  return dialogOptions.value.some(option => option.audio);
});

// 文字动画相关变量
let textAnimationInterval: number | null = null;
let currentCharIndex = 0;
let pendingOptions: DialogueOption[] = []; // 待显示的选项

// 音频播放相关
let currentAudio: HTMLAudioElement | null = null;
const playingOptionId = ref<string | null>(null); // 正在播放音频的选项ID

/**
 * 播放音频
 * @param audioPath 音频路径
 * @returns Promise，音频播放完成后 resolve
 */
const playAudio = (audioPath: string): Promise<void> => {
  return new Promise((resolve, reject) => {
    try {
      currentAudio = new Audio();
      // 设置跨域属性，解决 COEP 跨域问题
      currentAudio.crossOrigin = 'anonymous';
      currentAudio.src = audioPath;
      currentAudio.onended = () => {
        currentAudio = null;
        resolve();
      };
      currentAudio.onerror = (e) => {
        console.error('音频播放失败:', audioPath, e);
        currentAudio = null;
        resolve(); // 即使出错也继续流程
      };
      currentAudio.play().catch((e) => {
        console.error('音频播放失败:', audioPath, e);
        resolve();
      });
    } catch (e) {
      console.error('音频创建失败:', audioPath, e);
      resolve();
    }
  });
};

/**
 * 停止当前播放的音频
 */
const stopCurrentAudio = () => {
  if (currentAudio) {
    currentAudio.pause();
    currentAudio.currentTime = 0;
    currentAudio = null;
  }
  playingOptionId.value = null;
};

// 文字动画函数
const animateText = () => {
  if (currentCharIndex < fullText.length) {
    displayedText.value = fullText.substring(0, currentCharIndex + 1);
    currentCharIndex++;
  } else {
    textAnimationInterval && clearInterval(textAnimationInterval);
    textAnimationInterval = null;
    isTyping.value = false;
    // 动画完成后显示选项
    dialogOptions.value = pendingOptions;
  }
};

// 开始文字动画
const startTextAnimation = () => {
  currentCharIndex = 0;
  displayedText.value = '';
  isTyping.value = true;
  dialogOptions.value = []; // 先清空选项

  if (textAnimationInterval) {
    clearInterval(textAnimationInterval);
  }

  textAnimationInterval = setInterval(animateText, 50);
};

// 跳过打字动画，直接显示全部文字和选项
const skipTypingAnimation = () => {
  if (!isTyping.value) return;

  // 停止动画
  if (textAnimationInterval) {
    clearInterval(textAnimationInterval);
    textAnimationInterval = null;
  }

  // 直接显示全部文字
  displayedText.value = fullText;
  isTyping.value = false;

  // 显示选项
  dialogOptions.value = pendingOptions;
};


/**
 * 显示NPC对话
 */
const show = (data: NPCInteractionData) => {
  currentInteractionData = data;
  npcName.value = data.npcName;
  showLegacyButton.value = false;

  if (data.dialogues && data.dialogues.length > 0) {
    currentDialogues.value = data.dialogues;
    showDialogue(data.dialogues[0]);
  } else {
    fullText = `你好，我是${data.npcName}。`;
    pendingOptions = [{ id: 'goodbye', text: '再见' }];
    startTextAnimation();
  }

  showDialog.value = true;
};

/**
 * 显示特定对话节点
 */
const showDialogue = async (dialogue: DialogueOption) => {
  fullText = dialogue.text;

  // 如果NPC对话有音频，自动播放
  if (dialogue.audio) {
    playAudio(dialogue.audio);
  }

  // 判断是否需要添加默认的"再见"选项
  const hasOriginalResponses = dialogue.responses && dialogue.responses.length > 0;
  const responses = hasOriginalResponses
    ? dialogue.responses!
    : [{ id: 'goodbye', text: '再见' }];

  // 当原始配置只有一个选项时，自动处理（不显示选项）
  // 但如果是自动生成的"再见"选项，则需要显示出来让用户点击
  if (hasOriginalResponses && responses.length === 1) {
    const singleResponse = responses[0];
    pendingOptions = []; // 不显示选项

    startTextAnimation();

    // 监听文字动画完成
    const checkComplete = setInterval(() => {
      if (!isTyping.value) {
        clearInterval(checkComplete);

        if (singleResponse.action) {
          singleResponse.action();
        }

        const isEndOption = singleResponse.id === 'goodbye' ||
                           singleResponse.id.includes('bye') ||
                           !singleResponse.responses ||
                           singleResponse.responses.length === 0;

        if (isEndOption) {
          hide();
        } else {
          // 继续显示NPC的下一条回复
          showDialogue(singleResponse.responses![0]);
        }
      }
    }, 100);
  } else {
    // 多个选项或自动生成的"再见"选项，等动画完成后显示
    pendingOptions = responses;
    startTextAnimation();
  }
};

/**
 * 处理播放音频按钮点击
 * 仅播放音频，不进入选项
 */
const handlePlayAudio = async (option: DialogueOption) => {
  if (!option.audio) return;

  // 如果正在播放同一个选项的音频，则停止
  if (playingOptionId.value === option.id) {
    stopCurrentAudio();
    return;
  }

  // 先停止之前的音频（但不清除 playingOptionId）
  if (currentAudio) {
    currentAudio.pause();
    currentAudio.currentTime = 0;
    currentAudio = null;
  }

  // 设置当前播放的选项ID
  playingOptionId.value = option.id;
  await playAudio(option.audio);
  playingOptionId.value = null;
};

/**
 * 进入选项的后续流程
 */
const proceedWithOption = (option: DialogueOption) => {
  dialogOptions.value = []; // 清空选项

  if (option.action) {
    option.action();
  }

  // 如果选项有后续对话，显示NPC的回复
  if (option.responses && option.responses.length > 0) {
    showDialogue(option.responses[0]);
  } else if (option.id === 'goodbye' || !option.responses) {
    hide();
  }
};

/**
 * 处理对话选项点击
 * 直接进入选项，不播放音频
 */
const handleOptionClick = (option: DialogueOption) => {
  // 停止正在播放的音频
  stopCurrentAudio();

  proceedWithOption(option);
};

/**
 * 隐藏对话框
 */
const hide = () => {
  // 停止音频
  stopCurrentAudio();

  showDialog.value = false;
  npcName.value = '';
  dialogOptions.value = [];
  currentDialogues.value = [];
  currentInteractionData = null;
  isTyping.value = false;
  pendingOptions = [];
  if (textAnimationInterval) {
    clearInterval(textAnimationInterval);
    textAnimationInterval = null;
  }
};

defineExpose({
  show,
  hide,
});
</script>

