// 🔥 从配置初始化 HDRI 状态
function initHDRIFromConfig() {
  if (!props.sceneManager) return;

  const hdriConfig = props.sceneManager.getHDRIConfig();

  if (hdriConfig?.url) {
    // 配置中有 HDRI，同步到面板状态
    hdrFileName.value = hdriConfig.url.split('/').pop() || 'config-hdri';
