    hdriParams.intensity = props.sceneManager.getEnvironmentIntensity();
    hdriParams.background = props.sceneManager.isHDRIBackgroundEnabled();
    hdriParams.backgroundBlurriness = props.sceneManager.getBackgroundBlurriness();
