// 🔥 从配置初始化 Sky 状态
function initSkyFromConfig() {
  if (!props.sceneManager) return;

  // 从 SceneManager 获取当前 Sky 设置
  skyEnabled.value = props.sceneManager.isSkyEnabled();
  const params = props.sceneManager.getSkyParams();
  skyParams.turbidity = params.turbidity;
  skyParams.rayleigh = params.rayleigh;
  skyParams.mieCoefficient = params.mieCoefficient;
  skyParams.mieDirectionalG = params.mieDirectionalG;
  skyParams.elevation = params.elevation;
  skyParams.azimuth = params.azimuth;

  // 检测当前配置是否匹配某个预设
  skyPreset.value = detectSkyPreset();

  console.log(`🌤️ 已同步 Sky: enabled=${skyEnabled.value}, preset=${skyPreset.value}, elevation=${skyParams.elevation}°, azimuth=${skyParams.azimuth}°`);
}

// 🔥 检测当前天空参数是否匹配某个预设
function detectSkyPreset(): string {
  for (const [presetName, preset] of Object.entries(skyPresets)) {
    if (
      Math.abs(skyParams.turbidity - preset.turbidity) < 0.1 &&
      Math.abs(skyParams.rayleigh - preset.rayleigh) < 0.1 &&
      Math.abs(skyParams.mieCoefficient - preset.mieCoefficient) < 0.001 &&
      Math.abs(skyParams.mieDirectionalG - preset.mieDirectionalG) < 0.01 &&
      Math.abs(skyParams.elevation - preset.elevation) < 1 &&
      Math.abs(skyParams.azimuth - preset.azimuth) < 5
    ) {
      return presetName;
    }
  }
  return 'custom';
}

// 🔥 天空预设变化处理
function onSkyPresetChange() {
  if (!props.sceneManager || !skyEnabled.value) return;

  const preset = skyPresets[skyPreset.value];
  if (!preset) return; // 自定义模式不做处理

  // 应用预设参数到本地状态
  skyParams.turbidity = preset.turbidity;
  skyParams.rayleigh = preset.rayleigh;
  skyParams.mieCoefficient = preset.mieCoefficient;
  skyParams.mieDirectionalG = preset.mieDirectionalG;
  skyParams.elevation = preset.elevation;
  skyParams.azimuth = preset.azimuth;

  // 应用到 SceneManager
  props.sceneManager.setSkyParams(skyParams);

  console.log(`🌤️ 已应用天空预设: ${skyPreset.value}`);
}

