// 🔥 HDR 文件上传相关方法
function triggerFileInput() {
  hdrFileInput.value?.click();
}

function onFileSelect(event: Event) {
  const input = event.target as HTMLInputElement;
  const file = input.files?.[0];
  if (file) {
    processHDRFile(file);
  }
}

function onDragOver() {
  isDragOver.value = true;
}

function onDragLeave() {
  isDragOver.value = false;
}

function onFileDrop(event: DragEvent) {
  isDragOver.value = false;
  const file = event.dataTransfer?.files?.[0];
  if (file) {
    processHDRFile(file);
  }
}

function processHDRFile(file: File) {
  // 检查文件类型
  const validTypes = ['.hdr', '.jpg', '.jpeg', '.png'];
  const fileName = file.name.toLowerCase();
  const isValid = validTypes.some((type) => fileName.endsWith(type));

  if (!isValid) {
    console.warn('⚠️ 不支持的文件格式，请上传 .hdr.jpg, .hdr, .jpg 或 .png 文件');
    return;
  }

  // 释放之前的 URL
  if (hdrFileUrl.value) {
    URL.revokeObjectURL(hdrFileUrl.value);
  }

  // 创建本地文件 URL
  hdrFileUrl.value = URL.createObjectURL(file);
  hdrFileName.value = file.name;
  console.log(`📁 已选择 HDR 文件: ${file.name}`);
}

function clearHDRFile() {
  if (hdrFileUrl.value) {
    URL.revokeObjectURL(hdrFileUrl.value);
  }
  hdrFileUrl.value = '';
  hdrFileName.value = '';
  if (hdrFileInput.value) {
    hdrFileInput.value.value = '';
  }
}

// 🔥 加载 HDR 环境方法
function onLoadHDREnvironment() {
  if (props.sceneManager && hdrFileUrl.value) {
    // 传递文件名用于判断格式（blob URL 不包含后缀）
    props.sceneManager.loadDebugUltraHDR(hdrFileUrl.value, hdrFileName.value);
    isHDRLoaded.value = true;
    console.log(`🌅 加载 HDR 环境: ${hdrFileName.value}`);
  } else {
    console.warn('⚠️ SceneManager 未初始化或未选择文件，无法加载 HDR 环境');
  }
}

// 🔥 卸载 HDR 环境方法
function onUnloadHDREnvironment() {
  if (props.sceneManager) {
    props.sceneManager.removeDebugUltraHDR();
    isHDRLoaded.value = false;
    // 重置 HDRI 参数到默认值
    hdriParams.intensity = 1.0;
    hdriParams.background = true;
    hdriParams.backgroundBlurriness = 0;
    hdriParams.backgroundIntensity = 1.0;
    hdriParams.exposure = 1.0;
    console.log('🌅 卸载 HDR 环境');
  } else {
    console.warn('⚠️ SceneManager 未初始化，无法卸载 HDR 环境');
  }
}

