// NPC相关方法
function setNPCPositionToPlayer() {
  if (props.physicsWorldManager) {
    const playerPos = props.physicsWorldManager.getCharacterPosition();
    npcCreatePosition.x = Math.round(playerPos.x * 10) / 10;
    npcCreatePosition.y = Math.round(playerPos.y * 10) / 10;
    npcCreatePosition.z = Math.round(playerPos.z * 10) / 10;
    console.log(
      `📍 NPC创建位置已设置为玩家位置: (${npcCreatePosition.x}, ${npcCreatePosition.y}, ${npcCreatePosition.z})`,
    );
  }
}

async function createSingleNPC() {
  try {
    const config = {
      position: { x: npcCreatePosition.x, y: npcCreatePosition.y, z: npcCreatePosition.z },
      modelId: selectedNPCModelId.value || undefined,
    };

    if (props.npcManager) {
      await props.npcManager.createNPC(config);
      updateNPCList();
    }
  } catch (error) {
    console.error('创建NPC失败:', error);
  }
}

async function createRandomNPCs() {
  try {
    if (props.npcManager) {
      const centerPosition = { x: npcCreatePosition.x, y: npcCreatePosition.y, z: npcCreatePosition.z };
      await props.npcManager.createRandomNPCsInArea(centerPosition, 3, 5);
      updateNPCList();
    }
  } catch (error) {
    console.error('批量创建NPC失败:', error);
  }
}

