    const npc = props.npcManager.getNPC(npcId);
    if (npc) {
      // 在不同动画之间切换
      const animations = ['Idle', 'Walking', 'Running'];
      const currentIndex = Math.floor(Math.random() * animations.length);
      const animationName = animations[currentIndex];

      props.npcManager.setNPCAnimation(npcId, animationName, true);
      console.log(`NPC ${npcId} 动画切换为: ${animationName}`);
    }
  }
}

